namespace CloudServer; public partial class App : System.Windows.Application { readonly CancellationTokenSource apiCancellation=new(); System.Threading.Tasks.Task? apiTask; protected override void OnStartup(System.Windows.StartupEventArgs e){base.OnStartup(e);StateStore store;try{store=new StateStore();}catch(Exception ex){System.Windows.MessageBox.Show("Die Serverkonfiguration konnte nicht geladen werden. Der Server wurde aus Sicherheitsgründen nicht gestartet.\n\n"+ex.Message+"\n\nBitte prüfen Sie state.json und state.json.bak unter ProgramData\\i-NET-PROMO\\Cloudservice.","Serverkonfiguration",System.Windows.MessageBoxButton.OK,System.Windows.MessageBoxImage.Error);Shutdown();return;}if(store.State.Users.Count==0){var setup=new FirstRunWindow();if(setup.ShowDialog()!=true){Shutdown();return;}store.State.Users.Add(new UserAccount{UserName=setup.UserName,DisplayName=setup.DisplayName,IsAdmin=true,PasswordHash=StateStore.Hash(setup.Password),QuotaBytes=0});store.Save();}var admin=new AdminWindow(store);admin.Show();admin.SetApiStarting();apiTask=System.Threading.Tasks.Task.Run(()=>Api.Run(store,apiCancellation.Token,()=>Dispatcher.Invoke(admin.SetApiStarted)));apiTask.ContinueWith(t=>{if(t.IsFaulted)Dispatcher.Invoke(()=>admin.SetApiStatus(t.Exception?.GetBaseException()));else if(!apiCancellation.IsCancellationRequested)Dispatcher.Invoke(()=>admin.SetApiStatus(null));},System.Threading.Tasks.TaskScheduler.Default);} protected override void OnExit(System.Windows.ExitEventArgs e){apiCancellation.Cancel();try{apiTask?.Wait(TimeSpan.FromSeconds(11));}catch(System.AggregateException){}apiCancellation.Dispose();base.OnExit(e);} }